package project

// Add returns the sum of a and b.
func Add(a, b int) int {
	return a + b
}

package project

import (
	"testing"

	"github.com/stretchr/testify/assert"
	"github.com/stretchr/testify/require"
)

func TestAdd(t *testing.T) {
	require.Equal(t, 4, Add(2, 2))
	assert.Equal(t, 0, Add(-1, 1))
	assert.Equal(t, -3, Add(-1, -2))
}

package project

import "errors"

// ErrNotFound is returned when a requested record does not exist.
var ErrNotFound = errors.New("not found")

// Store loads records by id.
type Store interface {
	Get(id string) (string, error)
}

// Service contains the greeting business logic.
type Service struct {
	store Store
}

// NewService wires a Service to its Store dependency.
func NewService(s Store) *Service {
	return &Service{store: s}
}

// Greet loads a name from the Store and greets it.
func (s *Service) Greet(id string) (string, error) {
	name, err := s.store.Get(id)
	if err != nil {
		return "", err
	}
	return "hello " + name, nil
}

package project

import (
	"testing"

	"github.com/stretchr/testify/assert"
	"github.com/stretchr/testify/mock"
	"github.com/stretchr/testify/require"
)

type mockStore struct {
	mock.Mock
}

func (m *mockStore) Get(id string) (string, error) {
	args := m.Called(id)
	return args.String(0), args.Error(1)
}

func TestServiceGreet(t *testing.T) {
	store := new(mockStore)
	store.On("Get", "42").Return("world", nil)

	msg, err := NewService(store).Greet("42")
	require.NoError(t, err)
	assert.Equal(t, "hello world", msg)
	store.AssertExpectations(t)
}

func TestServiceGreetNotFound(t *testing.T) {
	store := new(mockStore)
	store.On("Get", "missing").Return("", ErrNotFound)

	_, err := NewService(store).Greet("missing")
	assert.ErrorIs(t, err, ErrNotFound)
	store.AssertExpectations(t)
}
